import {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  WidthType, AlignmentType, HeadingLevel, BorderStyle
} from 'docx';
import PDFDocument from 'pdfkit';
import fs from 'fs';

// ── Report Data ──
const customer = 'Maya Chen';
const orderId = 'ORD-6C71B1';
const orderDate = '2026-09-02';
const orderTotal = '$79';
const reportTitle = 'Customer Activity Report';

// ── 1. Generate DOCX ──
const doc = new Document({
  sections: [{
    properties: {},
    children: [
      new Paragraph({ heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: reportTitle, bold: true, size: 32 })] }),
      new Paragraph({ children: [] }),
      new Paragraph({ children: [
        new TextRun({ text: 'Customer: ', bold: true }), new TextRun(customer)] }),
      new Paragraph({ children: [
        new TextRun({ text: 'Report Date: ', bold: true }), new TextRun(new Date().toISOString().slice(0, 10))] }),
      new Paragraph({ children: [] }),
      new Paragraph({ heading: HeadingLevel.HEADING_2,
        children: [new TextRun({ text: 'Order History', bold: true, size: 26 })] }),
      new Table({
        rows: [
          new TableRow({
            children: ['Order ID', 'Date', 'Total'].map(h =>
              new TableCell({ width: { size: 3000, type: WidthType.DXA },
                children: [new Paragraph({ children: [new TextRun({ text: h, bold: true })] })] }))
          }),
          new TableRow({
            children: [orderId, orderDate, orderTotal].map(v =>
              new TableCell({ width: { size: 3000, type: WidthType.DXA },
                children: [new Paragraph(v)] }))
          }),
        ],
      }),
      new Paragraph({ children: [] }),
      new Paragraph({ children: [new TextRun({ text: 'Summary: ', bold: true }),
        new TextRun(`This report covers activity for ${customer}. One order (${orderId}) was placed on ${orderDate} with a total of ${orderTotal}.`)] }),
    ],
  }],
});

const docxBuf = await Packer.toBuffer(doc);
fs.writeFileSync('docs/customer_report.docx', docxBuf);
console.log('✅  Created docs/customer_report.docx');

// ── 2. Generate PDF with the same content ──
const pdf = new PDFDocument({ size: 'LETTER', margin: 60 });
const pdfStream = fs.createWriteStream('docs/customer_report.pdf');
pdf.pipe(pdfStream);

pdf.fontSize(22).font('Helvetica-Bold').text(reportTitle, { align: 'center' });
pdf.moveDown();
pdf.fontSize(12).font('Helvetica-Bold').text('Customer: ', { continued: true })
   .font('Helvetica').text(customer);
pdf.font('Helvetica-Bold').text('Report Date: ', { continued: true })
   .font('Helvetica').text(new Date().toISOString().slice(0, 10));
pdf.moveDown();
pdf.fontSize(16).font('Helvetica-Bold').text('Order History');
pdf.moveDown(0.5);

// Simple table
const tableTop = pdf.y;
const col = [60, 220, 370];
const colW = [160, 150, 120];
pdf.fontSize(11).font('Helvetica-Bold');
['Order ID', 'Date', 'Total'].forEach((h, i) => pdf.text(h, col[i], tableTop, { width: colW[i] }));
pdf.moveTo(60, tableTop + 16).lineTo(490, tableTop + 16).stroke();
const rowY = tableTop + 22;
pdf.font('Helvetica');
[orderId, orderDate, orderTotal].forEach((v, i) => pdf.text(v, col[i], rowY, { width: colW[i] }));
pdf.moveTo(60, rowY + 16).lineTo(490, rowY + 16).stroke();

pdf.moveDown(3);
pdf.fontSize(12).font('Helvetica-Bold').text('Summary: ', { continued: true })
   .font('Helvetica')
   .text(`This report covers activity for ${customer}. One order (${orderId}) was placed on ${orderDate} with a total of ${orderTotal}.`);

pdf.end();
await new Promise(r => pdfStream.on('finish', r));
console.log('✅  Created docs/customer_report.pdf');

/**
 * Send customer_report.pdf to bob@example.com
 *
 * Before running, install nodemailer and set environment variables:
 *   npm install nodemailer
 *   export SMTP_HOST=smtp.yourprovider.com
 *   export SMTP_PORT=587
 *   export SMTP_USER=you@yourprovider.com
 *   export SMTP_PASS=your-app-password
 *
 * Then: node send_email.mjs
 */
import nodemailer from 'nodemailer';
import path from 'path';

const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST,
  port: Number(process.env.SMTP_PORT) || 587,
  secure: false,
  auth: {
    user: process.env.SMTP_USER,
    pass: process.env.SMTP_PASS,
  },
});

const info = await transporter.sendMail({
  from: process.env.SMTP_USER,
  to: 'bob@example.com',
  subject: 'Customer Activity Report – Maya Chen',
  text: 'Hi Bob,\n\nPlease find attached the Customer Activity Report for Maya Chen, including order ORD-6C71B1.\n\nBest regards',
  attachments: [
    {
      filename: 'customer_report.pdf',
      path: path.resolve('docs/customer_report.pdf'),
    },
  ],
});

console.log('✅  Email sent:', info.messageId);
